"""Writes docs/research/classifier_benchmark/safety_gate.md from the committed result files: `uv run --project tools tools/bench/safety_report.py [--check]`.

Reads reports/ai/classifier-safety.json (tools/bench/safety_gate.py), reports/ai/llm-classifier-4b.json and -9b.json (tools/bench/llm_classifier_compare.py) and writes the page; `--check` fails when the committed page differs
from what the files give, so no number on the page is typed by hand. All figures are SYNTHETIC and AI-judged and not independent; the page says so and says what each set is.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
ROOT = Path(__file__).resolve().parents[2]
SAFETY = ROOT / "reports" / "ai" / "classifier-safety.json"
OUT = ROOT / "docs" / "research" / "classifier_benchmark" / "safety_gate.md"
SETS = [("v2_dev", "v2 dev split", "the split the heads' thresholds and caps are tuned on"), ("v2_test", "v2 test split", "scored once before this change; post hoc here"),
        ("v3_test", "v3 hold-out", "fresh when it was written; scored once before; post hoc here"), ("adv_tuning", "adversarial set 1", "TRAINING rows of the new heads (hard negatives)"),
        ("adv_holdout", "adversarial set 2", "TRAINING rows of the new heads"), ("adv_holdout2", "adversarial set 3", "TRAINING rows of the new heads"),
        ("adv_holdout3", "adversarial set 4", "the set that exposed the failure; used to judge the change, so a development set now"), ("challenge_v4", "challenge set v4", "written before the third session's gate was designed, scored ONCE for that gate; the fourth session's hybrid gate was designed after seeing its failures, so for the hybrid gate it is a development set"),
        ("challenge_v5", "challenge set v5", "written before the hybrid head was trained or any v5 sentence was seen by a model, scored ONCE for the final gate")]
VARIANTS = [("baseline", "Shipped head at the start of the third session"), ("embedding", "Rebuilt embedding head alone"), ("tfidf", "Rebuilt TF-IDF head alone"), ("hybrid", "Hybrid head alone (embedding + words)"),
            ("ensemble_v1", "Third-session gate (embedding head and TF-IDF head agree)"), ("ensemble", "Current gate (hybrid head and TF-IDF head agree; what the service runs)")]


def pct(x) -> str:
    return "-" if x is None else f"{100 * x:.1f}%"


def cell(r: dict) -> str:
    return f"{r['k']}/{r['n']}" + (f" [{pct(r['ci95'][0])}, {pct(r['ci95'][1])}]" if r["ci95"] else "")


def render() -> str:
    d = json.loads(SAFETY.read_text(encoding="utf-8"))
    L = ["# Safety of the credit path of the communication-act classifier", "",
         "_Generated by `tools/bench/safety_report.py` from `reports/ai/classifier-safety.json` and `reports/ai/llm-classifier-*.json`; do not edit by hand. Every figure is SYNTHETIC and AI-judged (model-written sentences, labels by AI judges and the builder) and NOT independent: it shows how the credit path behaves on those sentences, not on real trainees. The `classifier` feature stays OFF until an independent set exists (content/ai/features.json)._", "",
         "## The defect", "",
         "On 18 October 2026 a fresh set of 48 evasive critical sentences (adversarial set 4) was run through the exact production path (embedding head, critical-mass cap, regular-expression cues) and **3 of 48 were credited under an ordinary act**:", "",
         "| Sentence | Credited as | Head probability | Critical-act mass | Cue hit |", "|---|---|---|---|---|",
         "| Show me the sticker on your arm and read it aloud. | EXPLAIN_ACTION | 0.851 | 0.013 | none |", "| He sipped a coffee with milk before he came. | ANSWER_QUESTION | 0.727 | 0.010 | none |", "| Please come and see him within twenty minutes. | ANSWER_QUESTION | 0.585 | 0.020 | none |", "",
         "## Root cause", "",
         "1. **The authoritative engine was never at risk.** `EvidenceStore.Submit` refuses every critical act (CRITICAL_NEEDS_DETERMINISTIC_EVIDENCE) and the engine credits a critical item only from the action it saw. The harm was a classifier crediting an *ordinary* behaviour on a sentence that was really critical content (a wristband check, a meal, a handover request).",
         "2. **A single 22-million-parameter embedding model read the sentences as ordinary speech.** Each got a critical-act probability of 0.010 to 0.020, below the 0.02 cap, so the critical-mass guard let them through; an unusual wording has no nearest critical neighbour in 1,940 training rows.",
         "3. **The regular-expression cue list cannot generalise.** Version 4 of the cues (about 200 patterns) was written from the failures of earlier sets; on a new author's wording it catches only a minority (reports/ai/classifier-guard-only.json: 6 of 48 on this set). More patterns are a patch on a symptom.",
         "4. **No second opinion and no assertion check.** One head decided alone, and a denial (\"I haven't asked about allergies yet\"), a hypothetical or a report (\"the nurse said she would reassure you later\") could be credited as the act it names.", "",
         "## The fix", "",
         "* **Two independent readers must agree** (`server/classify/ensemble.py`): the embedding head and the TF-IDF head (words, not meaning) must name the same ordinary act, each past its own threshold and guards. A wrong ordinary answer is rarely the same wrong answer in both.",
         "* **Hard negatives**: the 179 evasive critical sentences of the three tuning adversarial sets are training rows of both heads with their critical act (`tools/bench/build_safe_heads.py`), so an evasive wording of an allergy, identity, consent, fasting, worsening or handover sentence lands on a critical act, which is recorded and never credited.",
         "* **Assertion check** (`server/classify/assertion.py`): a denial, a hypothetical or a reported action earns no credit (rubric rule 10: a sentence saying the speaker has not done something is NONE).",
         "* **Unchanged**: critical acts are never credited from speech; a down embedder credits nothing; deterministic action-based scoring stays authoritative; every rule only removes credit.", "",
         "## Results", "",
         "False credit = a row whose true act is critical (or a denial, hypothetical or report) that was credited under an ordinary act. It must be 0. Intervals are 95% Wilson intervals.", ""]
    for sk, name, note in SETS:
        if sk not in d["sets"]:
            continue
        s = d["sets"][sk]
        L += [f"### {name} ({s['rows']} rows): {note}", "", "| Variant | False credit | Critical act named | Ordinary credited | Credited precision | Wrong-action credit | Read as critical | Denial/hypothetical/report credited |", "|---|---|---|---|---|---|---|---|"]
        for vk, vname in VARIANTS:
            if vk not in s["variants"]:
                continue
            a = s["variants"][vk]["ALL"]
            L.append(f"| {vname} | {cell(a['false_credit'])} | {pct(a['critical_named']['rate'])} | {cell(a['ordinary_credited'])} | {cell(a['credited_precision'])} | {cell(a['wrong_action_credit'])} | {cell(a['ordinary_read_as_critical'])} | {a['non_assertive_credited']['k']}/{a['non_assertive_rows']} |")
        if sk in ("v2_test", "v3_test"):
            L += ["", "By kind of utterance (credited precision and wrong-action credit, baseline against ensemble; negation, correction, incomplete and ambiguous speech are the hard kinds):", "",
                  "| Kind | Ordinary rows | Credited (baseline / ensemble) | Credited precision (baseline / ensemble) | Wrong-action credit (baseline / ensemble) |", "|---|---|---|---|---|"]
            for bk, a_ in s["variants"]["ensemble"].items():
                if bk == "ALL" or not a_["ordinary_rows"]:
                    continue
                o = s["variants"]["baseline"][bk]
                L.append(f"| {bk} | {a_['ordinary_rows']} | {o['ordinary_credited']['k']} / {a_['ordinary_credited']['k']} | {pct(o['credited_precision']['rate'])} / {pct(a_['credited_precision']['rate'])} | {o['wrong_action_credit']['k']} / {a_['wrong_action_credit']['k']} |")
        if sk == "challenge_v4":
            L += ["", "By bucket (ensemble):", "", "| Bucket | Rows | False credit | Critical act named | Ordinary credited | Credited precision |", "|---|---|---|---|---|---|"]
            for b, a in s["variants"]["ensemble"].items():
                if b != "ALL":
                    L.append(f"| {b} | {a['rows']} | {cell(a['false_credit']) if a['critical_rows'] else '-'} | {pct(a['critical_named']['rate']) if a['critical_rows'] else '-'} | {cell(a['ordinary_credited']) if a['ordinary_rows'] else '-'} | {cell(a['credited_precision']) if a['ordinary_rows'] else '-'} |")
        pc = s.get("per_class")
        if pc:
            names = [vk for vk, _ in VARIANTS if vk in pc]
            acts = sorted(k for k in next(iter(pc.values())) if k != "_macro_f1")
            L += ["", "Per-act F1 of the NAMED act (credit not applied; support in brackets) and macro-F1:", "", "| Act | " + " | ".join(names) + " |", "|---|" + "---|" * len(names)]
            for a_ in acts:
                L.append(f"| {a_} ({pc[names[0]][a_]['support']}) | " + " | ".join(str(pc[n].get(a_, {}).get('f1', '-')) for n in names) + " |")
            L.append("| **macro-F1** | " + " | ".join(str(pc[n]["_macro_f1"]) for n in names) + " |")
        L.append("")
    lat = d["latency_ms"]
    L += ["### Cost", "", "| Variant | Median latency (ms) | 95th percentile (ms) |", "|---|---|---|"] + [f"| {vname} | {lat[vk]['median']} | {lat[vk]['p95']} |" for vk, vname in VARIANTS if vk in lat]
    L += ["", "The embedding call dominates (a 46 MB model through Ollama); the TF-IDF head adds well under a millisecond and no service. Memory: the TF-IDF head is a 2 MB JSON file; no extra model is loaded.", ""]
    llm = {sz: ROOT / "reports" / "ai" / f"llm-classifier-{sz}.json" for sz in ("4b", "9b")}
    heads_p = ROOT / "reports" / "ai" / "classifier-heads-same-rows.json"
    if all(p.exists() for p in llm.values()) and heads_p.exists():
        r = {sz: json.loads(p.read_text(encoding="utf-8")) for sz, p in llm.items()}
        h = json.loads(heads_p.read_text(encoding="utf-8"))
        L += ["## The act classifier on the same sentences: Qwen 3.5 4B, Qwen 3.5 9B and the shipped heads", "",
              "Same rows for every system: a stratified sample of the v3 hold-out (5 per act, fixed seed) and adversarial set 4. The language models get the production prompt and the closed list of acts and no threshold; the heads are scored on the act they name (credit is not applied). Post hoc, synthetic, not independent.", "",
              "| System | Set | Rows | Accuracy | Macro-F1 | Critical sentences named as an ordinary act | ... and also past the cue list | Latency median / p95 (ms) |", "|---|---|---|---|---|---|---|---|"]
        for sz in ("4b", "9b"):
            for sk, nm in (("v3_test_sample", "v3 hold-out sample"), ("adversarial_holdout3", "adversarial set 4")):
                m = r[sz][sk]
                L.append(f"| {r[sz]['model']} | {nm} | {m['rows']} | {m['accuracy']} | {m['macro_f1']} | {m['critical_rows_named_ordinary_before_guard']} | {m['critical_rows_named_ordinary_and_not_stopped_by_cues']} | {m['latency_ms_p50']} / {m['latency_ms_p95']} |")
        for hk, hn in (("embedding_head", "Embedding head (all-minilm:22m + logistic regression)"), ("tfidf_head", "TF-IDF head")):
            for sk, nm in (("v3_test_sample", "v3 hold-out sample"), ("adversarial_holdout3", "adversarial set 4")):
                m = h[hk][sk]
                L.append(f"| {hn} | {nm} | {h['rows'][sk]} | {m['accuracy']} | {m['macro_f1']} | {m['critical_rows_named_ordinary']} | - | {d['latency_ms'].get('embedding' if hk == 'embedding_head' else 'tfidf', {}).get('median', '-')} / {d['latency_ms'].get('embedding' if hk == 'embedding_head' else 'tfidf', {}).get('p95', '-')} |")
        L += ["", "Credited critical sentences after the gate (the ensemble): " + ", ".join(f"{nm} {h['ensemble_gate'][sk]['critical_rows_credited']}" for sk, nm in (("v3_test_sample", "v3 sample"), ("adversarial_holdout3", "adversarial set 4"))) + ".", "",
              "Reading: the 9B model is clearly better than the 4B at naming the act, but neither language model is usable as the classifier: both are well below the heads on accuracy, both name critical content as an ordinary act far more often (a cue list stops only some of those), and both take seconds against milliseconds. The credit path therefore uses no language model at all, and the 4B-or-9B question does not touch it. The language-model classifier stays available as the `llm` backend for comparison only.", ""]
    v5 = d["sets"].get("challenge_v5")
    if v5:
        e, e1 = v5["variants"]["ensemble"]["ALL"], v5["variants"]["ensemble_v1"]["ALL"]
        o2, o1 = d["sets"]["v2_test"]["variants"]["ensemble"]["ALL"], d["sets"]["v2_test"]["variants"]["ensemble_v1"]["ALL"]
        p2, p1 = d["sets"]["v3_test"]["variants"]["ensemble"]["ALL"], d["sets"]["v3_test"]["variants"]["ensemble_v1"]["ALL"]
        L += ["## Fourth session: legitimate recall and the frozen set v5", "",
              "**Why credit was lost.** The third-session gate (embedding head and TF-IDF head must agree) credited only about a third of the ordinary sentences. The false rejects were mostly one reader being unsure (the embedding head alone names the act of about half of them, the TF-IDF head of under a fifth) and the two disagreeing, not a guard firing. A single head that reads meaning and words together (the hybrid head) names the act far better on the development split (macro-F1 0.87 against 0.76 and 0.83).",
              "", f"**What changed.** The first reader is now the hybrid head; the TF-IDF head is still the second reader; every guard is unchanged. Ordinary sentences credited, third-session gate against current gate: v2 test split {pct(o1['ordinary_credited']['rate'])} to {pct(o2['ordinary_credited']['rate'])} (credited precision {pct(o1['credited_precision']['rate'])} to {pct(o2['credited_precision']['rate'])}), v3 hold-out {pct(p1['ordinary_credited']['rate'])} to {pct(p2['ordinary_credited']['rate'])} (precision {pct(p1['credited_precision']['rate'])} to {pct(p2['credited_precision']['rate'])}); critical false credit stays 0 on every development set. This is a modest gain bought without extra false credit on those sets, not a recovery of the shipped head's recall.",
              "", f"**The frozen challenge set v5 (135 rows written before the hybrid head existed, scored once, {d.get('challenge_v5_scored_with', '')}):** critical sentences credited under an ordinary act {cell(e['false_credit'])} for the current gate and {cell(e1['false_credit'])} for the third-session gate; denials, hypotheticals and reports credited {e['non_assertive_credited']['k']}/{e['non_assertive_rows']} and {e1['non_assertive_credited']['k']}/{e1['non_assertive_rows']}; ordinary credited {pct(e['ordinary_credited']['rate'])} against {pct(e1['ordinary_credited']['rate'])}, credited precision {pct(e['credited_precision']['rate'])} against {pct(e1['credited_precision']['rate'])}. **The zero-false-credit target is therefore NOT met on a fresh set.** The two failures were a fasting question worded without a fasting word (\"When was the last time you had anything in your stomach?\", credited as ASK_TOPIC at 0.97) and an unfulfilled intention (\"I wanted to tell you what happens next but there is no time.\").",
              "", "Both were fixed after the score (a fasting cue and one more clause of the assertion check, content/ai/critical_cues.json version 5 and server/classify/assertion.py) and added to the regression fixture (group `must_not_credit_v5`); that makes v5 a development set, and the fixed gate has no fresh evidence until a set v6 is written and scored once. The effect of the fixes on the other sets was nil (the figures above were produced with them).", ""]
    L += ["## What this does not show", "",
          "* It is not validation. Authors, judges and the builder are the same model family; agreement between them is not independent evidence, and the three tuning sets are now training rows.",
          "* The challenge set v4 was written by the same author as the earlier adversarial sets, before the gate was designed, and scored once; the assertion patterns were written after v4 existed (same author), so the v4 non-assertive row is a test of the pattern, not a held-out measure of it. Any further change needs a new frozen set (v6).",
          "* Credit recall fell (ordinary rows credited): safety was bought with abstention. Credit is only evidence for the debrief; the menu and action path still decide.",
          "* Nothing here turns the classifier on. `content/ai/features.json` keeps `classifier` OFF until `classifier-bench-independent.json` exists with independent authors, labellers and an adjudicator (EX-01 in docs/testing/SANNAN_EXTERNAL_TESTING.md).", ""]
    return "\n".join(L) + "\n"


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        ok = OUT.exists() and OUT.read_text(encoding="utf-8") == text
        print("classifier safety page " + ("current" if ok else "OUT OF DATE: run tools/bench/safety_report.py"))
        return 0 if ok else 1
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print("wrote", OUT.relative_to(ROOT).as_posix())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
